// Copy ONNX Runtime Web's wasm/mjs assets into public/ort/.
//
// ORT loads its WebAssembly host at RUNTIME by URL, not through the bundler,
// so these files have to sit at a stable path the page can fetch. The
// vendored ARDY runtime points `ort.env.wasm.wasmPaths` at `/ort/`.
//
// They are derived from node_modules and total ~66 MB, so they are
// gitignored and regenerated by `npm run dev` / `npm run build` instead of
// being committed.
import { copyFile, mkdir, readdir } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';

const dist = fileURLToPath(new URL('../node_modules/onnxruntime-web/dist/', import.meta.url));
const dest = fileURLToPath(new URL('../public/ort/', import.meta.url));

// Only the WebAssembly host files. The JS API itself is bundled normally.
const wanted = (name) => /^ort-wasm-simd-threaded(\.[a-z]+)?\.(wasm|mjs)$/.test(name);

await mkdir(dest, { recursive: true });
let copied = 0;
for (const name of await readdir(dist)) {
  if (!wanted(name)) continue;
  await copyFile(`${dist}${name}`, `${dest}${name}`);
  copied += 1;
}
if (copied === 0) {
  throw new Error('No ONNX Runtime wasm assets found — is onnxruntime-web installed?');
}
console.log(`ort-assets: copied ${copied} files to public/ort/`);
